.darma-loader-tw-orbit-dot { position: relative; display: inline-block; width: var(--loader-size, 60px); height: var(--loader-size, 60px); border-radius: 9999px; border: calc(var(--loader-size, 60px) * .035) solid color-mix(in srgb, var(--loader-color, #06b6d4) 25%, transparent); animation: darma-loader-tw-orbit-dot-twOrbit calc(var(--loader-speed, 1s) * 1.6) linear infinite; }
.darma-loader-tw-orbit-dot .darma-loader-tw-orbit-dot__dot { position: absolute; top: calc(var(--loader-size, 60px) * -.1); left: 50%; width: calc(var(--loader-size, 60px) * .22); height: calc(var(--loader-size, 60px) * .22); margin-left: calc(var(--loader-size, 60px) * -.11); border-radius: 9999px; background: var(--loader-color, #06b6d4); box-shadow: 0 0 calc(var(--loader-size, 60px) * .12) color-mix(in srgb, var(--loader-color, #06b6d4) 55%, transparent); }
@keyframes darma-loader-tw-orbit-dot-twOrbit { to { transform: rotate(360deg); } }

